`,y.jsx(t.p,{children:"From this paper, I was introduced to this problem. I was familiar with basic search algorithms like linear search and binary search, but I realized how inefficient they would be for searching datasets with a very large number of data points, in the billions. There were several ways in which this problem could be solved, each with its own trade-offs. This paper discussed different algorithms in detail."}),`
`,y.jsx(t.h3,{id:"approximate-nearest-neighbour-search-annn",children:y.jsx(t.a,{href:"#approximate-nearest-neighbour-search-annn",children:"Approximate Nearest Neighbour Search (ANNN)"})}),`
`,y.jsx(t.p,{children:"Although Exact Nearest Neighbor Search (NNN) can solve the problem, it comes at the cost of a higher memory footprint and even higher search times. To improve upon this, Approximate Nearest Neighbor Search (ANNS) algorithms were introduced. This paper discusses various approaches to solving the ANNS problem, such as tree-based, graph-based, hashing-based, and quantization-based methods, providing deeper insights into these algorithms."}),`
`,y.jsx(t.h3,{id:"combining-llms-with-vector-database",children:y.jsx(t.a,{href:"#combining-llms-with-vector-database",children:"Combining LLMs with Vector Database"})}),`
`,y.jsx(t.p,{children:"Although vector databases (vector DBs) and large language models (LLMs) are individually powerful tools, combining them opens the door to a whole new level of possibilities. LLMs can leverage the storage capabilities provided by vector databases to deliver more efficient responses. Additionally, using LLMs on top of vector databases can enhance search efficiency by adding context to queries, thereby optimizing the performance of vector DBs. Numerous possibilities arise from this combination that can be further explored."}),`
`,y.jsx(t.h2,{id:"5-conclusion",children:y.jsx(t.a,{href:"#5-conclusion",children:"5. Conclusion"})}),`
`,y.jsx(t.p,{children:"Research paper gave really great insight on vector databases, underlying algorithms for NNN problem. I would highly suggest this paper to someone who want to start in this field. This paper might open new doors for you. Additionally this paper also leaves you with a interesting topic to research about i.e. Retrieval-Based LLM. I would definetly continue reading about this further. Hoping you will too."})]})}function kA(h={}){const{wrapper:t}={..._e(),...h.components};return t?y.jsx(t,{...h,children:y.jsx(xg,{...h})}):xg(h)}const NA=Object.freeze(Object.defineProperty({__proto__:null,default:kA,frontmatter:DA},Symbol.toStringTag,{value:"Module"})),jA={title:"⚙️ When to Use a MonoRepo: Benefits, Drawbacks, and Best Practices",date:"2024-09-08",tags:["Productivity","Misc"],readTime:"6",description:"Exploring MonoRepos: when a single repository boosts collaboration and code reuse, and when it creates complexity and friction."};function Ag(h){const t={a:"a",h2:"h2",h3:"h3",hr:"hr",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",..._e(),...h.components};return y.jsxs(y.Fragment,{children:[y.jsxs(t.p,{children:["When I first encountered the concept of a ",y.jsx(t.strong,{children:"MonoRepo"}),", it didn't quite make sense. 🤔 Why would anyone put all their code into a single repository? In my experience, each microservice had its own dedicated repository, built separately to reduce complexity. Combining everything into one place seemed like it would only increase developer effort and make things more confusing — until I came across this fascinating case study by Google."]}),`
