`,y.jsxs(t.p,{children:["With all projects in one place, managing shared dependencies became easier. Instead of updating libraries and tools across multiple repos, it only needed to be done once. However, this also became a challenge as all services needed to ",y.jsx(t.strong,{children:"agree on specific versions of libraries and tools"}),". ⚠️"]}),`
