`,y.jsxs(t.ol,{start:"4",children:[`
`,y.jsx(t.li,{children:"Worker reads the input, parses key/value pairs from this data, passes them to user-defined map function, gets intermediate keys from this function and buffers them in memory"}),`
`,y.jsx(t.li,{children:"Periodically this buffer is written into local disk as a spill file"}),`
`,y.jsx(t.li,{children:"Data is split into R partitions, each corresponding to a reduce task"}),`
`]}),`
`,y.jsx(t.h3,{id:"reduce-phase",children:y.jsx(t.a,{href:"#reduce-phase",children:"Reduce Phase"})}),`
`,y.jsxs(t.ol,{start:"7",children:[`
`,y.jsx(t.li,{children:"Location of these pairs are passed back to master node which passes this on to reduce workers"}),`
`,y.jsx(t.li,{children:"Reduce worker uses RPC to read the buffer data from local disk of map workers"}),`
`,y.jsx(t.li,{children:"Once reduce worker reads all data, it sorts these intermediate keys, using external sort if data is too large to fit in memory"}),`
`,y.jsx(t.li,{children:"It iterates over sorted intermediate data, passing each unique key's corresponding set of intermediate values to the reduce function"}),`
`,y.jsx(t.li,{children:"Output is appended to a final output file for this reduce partition"}),`
`]}),`
`,y.jsx(t.h2,{id:"fault-tolerance",children:y.jsx(t.a,{href:"#fault-tolerance",children:"Fault Tolerance"})}),`
