`,y.jsx(t.p,{children:"Master pings worker periodically, if no response is received from a worker for certain amount of time it is marked as failed. The system handles worker failures in the following ways:"}),`
`,y.jsxs(t.ul,{children:[`
`,y.jsx(t.li,{children:"Map tasks completed or in-progress by failed worker are reset back to idle state"}),`
`,y.jsx(t.li,{children:"These tasks become eligible to be rescheduled on other workers"}),`
`,y.jsx(t.li,{children:"Reduce tasks that have already read data from failed map task need to re-read it from new worker"}),`
`,y.jsx(t.li,{children:"Reduce tasks don't need to be re-executed since output is stored in global file system"}),`
`]}),`
`,y.jsx(t.h3,{id:"master-failure",children:y.jsx(t.a,{href:"#master-failure",children:"Master Failure"})}),`
`,y.jsx(t.p,{children:"The system handles master node failures through checkpointing:"}),`
`,y.jsxs(t.ul,{children:[`
`,y.jsx(t.li,{children:"Master periodically writes checkpoint of master data structures"}),`
